    orderedTags: import('comment-parser').Spec[],
    jsdoc: import('comment-parser').Block,
    utils: import('../iterateJsdoc').Utils,
): (() => void) => () => {
    const itemsToMoveRange = [
        ...Array.from({
            length: jsdoc.tags.length - firstChangedTagIndex,
