                !duplicateParams
                && paramTags.some(([, priorTag], priorIndex) => priorIndex < index && priorTag.name === tag.name)
            ) {
                return false;
            }

            if (tag.name.includes('.')) {
                dotted += 1;

                return false;
            }

            let functionParameterName = functionParameterNames[index - dotted + thisOffset];
            if (
                !documentsThis
                && functionParameterName === 'this'
                && tag.name.trim() !== 'this'
            ) {
                thisOffset += 1;
                functionParameterName = functionParameterNames[index - dotted + thisOffset];
            }

            if (!functionParameterName) {
                if (allowExtraTrailingParamDocs) {
                    return false;
                }

                const removeExtraParam = () => {
                    const currentTagIndex = jsdoc.tags.indexOf(tag);
                    if (currentTagIndex !== -1) {
                        utils.removeTag(currentTagIndex);
                    }
                };

                utils.reportJSDoc(
                    `@${targetTagName} "${tag.name}" does not match an existing function parameter.`,
                    tag,
                    extraParams ? removeExtraParam : null,
                    false,
                    undefined,
                    [
                        {
                            desc: `Remove the extra @${targetTagName} "${tag.name}".`,
                            handler: removeExtraParam,
                        },
                    ],
                );

                return true;
            }

            if (
                typeof functionParameterName === 'object'
                && 'name' in functionParameterName
                && Array.isArray(functionParameterName.name)
            ) {
                const actualName = tag.name.trim();
                const expectedName = functionParameterName.name[index];
                if (actualName === expectedName) {
                    thisOffset -= 1;
                    return false;
                }

                report(
                    `Expected @${targetTagName} name to be "${expectedName}". Got "${actualName}".`,
                    null,
                    tag,
                );
                return true;
            }

            if (Array.isArray(functionParameterName)) {
                if (!checkDestructured) {
                    return false;
                }

                if (tag.type && tag.type.search(checkTypesRegex) === -1) {
                    return false;
                }

                const [
                    parameterName,
                    {
                        annotationParamName,
                        hasPropertyRest,
                        names: properties,
                        rests,
                    },
                ] = functionParameterName as [
                    string | undefined,
                    import('../jsdocUtils').FlattendRootInfo & {
                        annotationParamName?: string | undefined;
                    },
                ];
                if (annotationParamName !== undefined) {
                    const name = tag.name.trim();
                    if (name !== annotationParamName) {
                        report(
                            `@${targetTagName} "${name}" does not match parameter name "${annotationParamName}"`,
                            null,
                            tag,
                        );
                    }
                }

                const tagName = parameterName === undefined
                    ? tag.name.trim()
                    : parameterName;
                const expectedNames = properties.map((name) => `${tagName}.${name}`);
                const actualNames = paramTags.map(([, paramTag]) => paramTag.name.trim());
                const actualTypes = paramTags.map(([, paramTag]) => paramTag.type);

                const missingProperties: { name: string; tagPlacement: { line: number } }[] = [];

                const notCheckingNames: string[] = [];

                Array.from(expectedNames.entries()).forEach(([idx, name]) => {
                    if (
                        notCheckingNames.some((notCheckingName) => name.startsWith(notCheckingName))
                    ) {
                        return;
                    }

                    const actualNameIdx = actualNames.findIndex(
                        (actualName) => utils.comparePaths(name)(actualName),
                    );
                    if (actualNameIdx === -1) {
                        if (!checkRestProperty && rests[idx]) {
                            return;
                        }

                        const missingIndex = actualNames.findIndex(
                            (actualName) => utils.pathDoesNotBeginWith(
                                name,
                                actualName,
                            ),
                        );
                        const line = tag.source[0]!.number
                            - 1
                            + (missingIndex > -1
                                ? missingIndex
                                : actualNames.length);
                        missingProperties.push({
                            name,
                            tagPlacement: {
                                line: line === 0 ? 1 : line,
                            },
                        });
                    } else if (
                        actualTypes[actualNameIdx]!.search(checkTypesRegex)
                            === -1
                        && actualTypes[actualNameIdx] !== ''
                    ) {
                        notCheckingNames.push(name);
                    }
                });

                const hasMissing = missingProperties.length;
                if (hasMissing) {
                    (missingProperties).forEach(({
                        name: missingProperty,
                        tagPlacement,
                    }) => {
                        report(
                            `Missing @${targetTagName} "${missingProperty}"`,
                            null,
                            tagPlacement,
                        );
                    });
                }

                if (!hasPropertyRest || checkRestProperty) {
                    const extraProperties: [
                        string,
                        import('comment-parser').Spec,
                    ][] = [];
                    Array.from(actualNames.entries()).forEach(([idx, name]) => {
                        const match = name.startsWith(`${tag.name.trim()}.`);
                        if (
                            match
                            && !expectedNames.some(utils.comparePaths(name))
                            && !utils.comparePaths(name)(tag.name)
                            && (!disableExtraPropertyReporting
                                || properties.some((prop) => (
                                    prop.split('.').length
                                        >= name.split('.').length - 1
                                )))
                        ) {
                            extraProperties.push([name, paramTags[idx]![1]]);
                        }
                    });

                    if (extraProperties.length) {
                        (extraProperties).forEach(([extraProperty, tg]) => {
                            report(
                                `@${targetTagName} "${extraProperty}" does not exist on ${tag.name}`,
                                null,
                                tg,
                            );
                        });

                        return true;
                    }
                }

                return hasMissing;
            }

            let funcParamName;
            if (typeof functionParameterName === 'object') {
                const { name } = functionParameterName;
                funcParamName = name;
            } else {
                funcParamName = functionParameterName;
            }

            if (funcParamName !== tag.name.trim()) {
                // Todo: Improve for array or object child items
                const actualNames = paramTagsNonNested.map(([, { name }]) => name.trim());

                const expectedNames = functionParameterNames
                    .map((item, idx) => {
                        if (
                            /**
              })]}
                             */ (
                                item as [
                                    string | undefined,
                                    import('../jsdocUtils').FlattendRootInfo & {
                                        annotationParamName?: string;
                                    },
                                ]
                            )?.[1]?.names
                        ) {
                            return actualNames[idx];
                        }

                        return item;
                    })
                    .filter((item) => documentsThis || item !== 'this');
                const message = `Expected @${targetTagName} names to be "${expectedNames
                    .map((expectedName) => (typeof expectedName === 'object'
                            && 'name' in expectedName
                            && expectedName.restElement
                        ? `...${expectedName.name}`
                        : expectedName))
                    .join(', ')}". Got "${actualNames.join(', ')}".`;

                if (isBadParamOrder) {
                    if (!badParamOrder) {
                        return false;
                    }

                    let orderFix = null;
                    if (enableFixer && canFixParamOrder) {
                        const orderedTags = JSON.parse(
                            JSON.stringify(jsdoc.tags),
                        ) as import('comment-parser').Spec[];
                        Array.from(expectedParamNames.entries()).forEach(([
                            paramIndex,
                            expectedName,
                        ]) => {
                            const matchingTag = paramTagsNonNested.find(
                                ([, candidateTag]) => (
                                    candidateTag.name.trim()
                                            === expectedName
                                ),
                            ) as [string, import('comment-parser').Spec];
                            orderedTags[
                                Number(paramTagsNonNested[paramIndex]![0])
                            ] = JSON.parse(JSON.stringify(matchingTag[1]));
                        });

                        const firstChangedParamIndex = actualParamNames.findIndex((name, paramIndex) => {
                            const expected = expectedParamNames[paramIndex];
                            return name !== expected;
                        });
                        orderFix = makeParamOrderFix(
                            Number(
                                paramTagsNonNested[firstChangedParamIndex]![0],
                            ),
                            orderedTags,
                            jsdoc,
                            utils,
                        );
                    }

                    utils.reportJSDoc(message, tag, orderFix, true);

                    return true;
                }

                // When disableMissingParamChecks is true tag names can be omitted.
                // Report when the tag names do not match the expected names or they are used out of order.
                if (disableMissingParamChecks) {
                    const usedExpectedNames = expectedNames
                        .map((a) => a?.toString())
                        .filter((expectedName) => (
                            expectedName
                                && actualNames.includes(expectedName)
                        ));
                    const usedInOrder = actualNames.every((actualName, idx) => actualName === usedExpectedNames[idx]);
                    if (usedInOrder) {
                        return false;
                    }
                }

                const renameBadParam = () => {
                    Object.assign(tag.source[0]!.tokens, { name: String(funcParamName) });
                };

                utils.reportJSDoc(
                    message,
                    tag,
                    badParamNames ? renameBadParam : null,
                    true,
                    undefined,
                    [
                        {
                            desc: `Rename @${targetTagName} "${tag.name.trim()}" to "${funcParamName}".`,
                            handler: renameBadParam,
                        },
                    ],
                );

                return true;
            }

            return false;
        },
    );
};

/**
 * @param targetTagName The target tag name value.
 * @param _allowExtraTrailingParamDocs The _allow extra trailing param docs value.
 * @param jsdocParameterNames The jsdoc parameter names value.
 * @param jsdoc The jsdoc value.
 * @param report The report value.
 * @returns The result of this check.
 */
const validateParameterNamesDeep = (
    targetTagName: string,
    _allowExtraTrailingParamDocs: boolean | undefined,
    jsdocParameterNames: {
        name: string;
        idx: import('../iterateJsdoc').Integer;
    }[],
    jsdoc: import('comment-parser').Block,
    report: import('../iterateJsdoc').Report,
): boolean => {
    let lastRealParameter: string;

    return jsdocParameterNames.some(({ idx, name: jsdocParameterName }) => {
        const isPropertyPath = jsdocParameterName.includes('.');

        if (isPropertyPath) {
            if (!lastRealParameter) {
                report(
                    `@${targetTagName} path declaration ("${jsdocParameterName}") appears before any real parameter.`,
                    null,
                    jsdoc.tags[idx],
                );

                return true;
            }

            let pathRootNodeName = jsdocParameterName.slice(
                0,
                jsdocParameterName.indexOf('.'),
            );

            if (pathRootNodeName.endsWith('[]')) {
                pathRootNodeName = pathRootNodeName.slice(0, -2);
            }

            if (pathRootNodeName !== lastRealParameter) {
                report(
                    `@${targetTagName} path declaration ("${jsdocParameterName}") root node name ("${pathRootNodeName}") `
                        + `does not match previous real parameter name ("${lastRealParameter}").`,
                    null,
                    jsdoc.tags[idx],
                );

                return true;
            }
        } else {
            lastRealParameter = jsdocParameterName;
        }

        return false;
    });
};

const allowedNodes = [
    'ArrowFunctionExpression',
    'FunctionDeclaration',
    'FunctionExpression',
    'TSDeclareFunction',
    // Add this to above defaults
    'TSMethodSignature',
    'TSPropertySignature',
];

export default iterateJsdoc(
    ({
        context, jsdoc, node, report, utils,
    }) => {
        const {
            allowExtraTrailingParamDocs,
            badParamNames = false,
            badParamOrder = true,
            checkDestructured = true,
            checkRestProperty = false,
            checkTypesPattern = '/^(?:[oO]bject|[aA]rray|PlainObject|Generic(?:Object|Array))$/',
            disableExtraPropertyReporting = false,
            disableMissingParamChecks = false,
            duplicateParams = true,
            enableFixer = false,
            extraParams = false,
            useDefaultObjectProperties = false,
        } = (context.options as Options)[0] || {};

        const nde = node as TSESTree.Node;

        // Although we might just remove global settings contexts from applying to
        //   this rule (as they can cause problems with `getFunctionParameterNames`
        //   checks if they are not functions but say variables), the user may
        //   instead wish to narrow contexts in those settings, so this check
        //   is still useful
        if (
            !allowedNodes.includes(nde.type)
            || (nde.type === 'TSPropertySignature' && (
                nde as TSESTree.TSPropertySignature
            )?.typeAnnotation?.typeAnnotation?.type !== 'TSFunctionType')
        ) {
            return;
        }

        const checkTypesRegex = utils.getRegexFromString(checkTypesPattern);

        const jsdocParameterNamesDeep = utils.getJsdocTagsDeep('param');
        if (!jsdocParameterNamesDeep || !jsdocParameterNamesDeep.length) {
            return;
        }

        const functionParameterNames = utils.getFunctionParameterNames(
            useDefaultObjectProperties,
        );

        const targetTagName = utils.getPreferredTagName({
            tagName: 'param',
        }) as string;
        const isError = validateParameterNames(
            targetTagName,
            allowExtraTrailingParamDocs,
            badParamNames,
            badParamOrder,
            checkDestructured,
            checkRestProperty,
            checkTypesRegex,
            disableExtraPropertyReporting,
            disableMissingParamChecks,
            duplicateParams,
            enableFixer,
            extraParams,
            functionParameterNames,
            jsdoc,
            utils,
            report,
        );

        if (isError || !checkDestructured) {
            return;
        }

        validateParameterNamesDeep(
            targetTagName,
            allowExtraTrailingParamDocs,
            jsdocParameterNamesDeep,
            jsdoc,
            report,
        );
    },
    {
        contextDefaults: allowedNodes,
        meta: {
            docs: {
